    {
      "topic": "contract",
      "statement": "On both supplied source sides, png_handle_zTXt accepts placement after IDAT, subject to the user chunk cache, valid keyword and compression type, successful CRC handling, and successful decompression; it then stores text through png_set_text_2.",
      "evidence": [
        {"unit_id": "u-dc30efc7b45c94477c61", "start_line": 2598, "end_line": 2620, "role": "primary", "dependency_reason": ""},
