    {
      "topic": "counterevidence",
      "statement": "png_read_info dispatches zTXt before IDAT when that feature is enabled, but stops at IDAT. A pre IDAT zTXt therefore provides a route to the handler, while it does not establish the frozen post IDAT route.",
      "evidence": [
        {"unit_id": "u-62a04c3f599eb18a9791", "start_line": 162, "end_line": 165, "role": "primary", "dependency_reason": ""},
