    {
      "topic": "trigger",
      "statement": "On both source sides, png_read_update_info initializes rows and sets PNG_FLAG_ROW_INIT; a subsequent png_start_read_image calls png_app_error for a duplicate initialization. The old entry calls them in that order before its row loop and png_read_end.",
      "evidence": [
        {"unit_id": "u-b53e493521e3901bcbc1", "start_line": 266, "end_line": 287, "role": "primary", "dependency_reason": ""},
